// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/auth/login", wrapper.Login)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/auth/session", wrapper.GetAuthenticatedSession)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/auth/logout", wrapper.Logout)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/account", wrapper.GetAccount)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/account", wrapper.UpdateAccount)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/account/locale", wrapper.UpdateAccountLocale)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/account/totp/enrollment", wrapper.StartTOTPEnrollment)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/account/totp", wrapper.DisableTOTP)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/account/totp", wrapper.ConfirmTOTPEnrollment)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/account/sessions", wrapper.RevokeAllSessions)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/system/status", wrapper.GetSystemStatus)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/nodes", wrapper.ListNodes)
	})
	r.Group(func(r chi.Router) {
		r.Delete(options.BaseURL+"/api/v1/nodes/{nodeId}", wrapper.DeleteNode)
	})
	r.Group(func(r chi.Router) {
		r.Patch(options.BaseURL+"/api/v1/nodes/{nodeId}", wrapper.UpdateNode)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/nodes/{nodeId}/revoke", wrapper.RevokeNode)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/agent-enrollment", wrapper.GetAgentEnrollment)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/api/v1/agent-enrollment", wrapper.UpdateAgentEnrollment)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/agent-enrollment/key", wrapper.RotateAgentEnrollmentKey)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/agent/enroll", wrapper.RegisterAgent)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/api/v1/agent/control", wrapper.PollAgent)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/api/v1/agent/configuration", wrapper.GetAgentConfiguration)
	})

	return r
}

